-- ============================================================================
-- Bound data access and approvals (plan: plans/bound-data-access-and-calendars.md)
-- ============================================================================
-- A16: AIAgentRun.BoundActionParams persists a run's bound action parameters,
--      so a run resumed from a stored request keeps them.
-- A17: QueryParameter.IsServerSet marks a parameter only server code may set.
-- A14: UserView.Properties holds a view's declared, typed inputs.
-- A17: an approval on queries, user views, dashboards and components, bound to
--      a fingerprint of the definition approved. Queries keep their Status
--      column as the approval status; the other three gain ApprovalStatus.
--
-- Additive only. CodeGen owns the EntityField rows, views, procedures and
-- generated classes. PostgreSQL counterpart is produced by the release build.
-- ============================================================================

ALTER TABLE [${flyway:defaultSchema}].[AIAgentRun] ADD
    [BoundActionParams] NVARCHAR(MAX) NULL;
GO

ALTER TABLE [${flyway:defaultSchema}].[QueryParameter] ADD
    [IsServerSet] BIT NOT NULL CONSTRAINT [DF_QueryParameter_IsServerSet] DEFAULT 0;
GO

ALTER TABLE [${flyway:defaultSchema}].[Query] ADD
    [ApprovalComments] NVARCHAR(MAX) NULL,
    [ApprovedByUserID] UNIQUEIDENTIFIER NULL,
    [ApprovedAt] DATETIMEOFFSET NULL,
    [ApprovedFingerprint] NVARCHAR(100) NULL,
    CONSTRAINT [FK_Query_ApprovedByUserID] FOREIGN KEY ([ApprovedByUserID]) REFERENCES [${flyway:defaultSchema}].[User]([ID]);
GO

ALTER TABLE [${flyway:defaultSchema}].[UserView] ADD
    [Properties] NVARCHAR(MAX) NULL,
    [ApprovalStatus] NVARCHAR(20) NOT NULL CONSTRAINT [DF_UserView_ApprovalStatus] DEFAULT N'Pending',
    [ApprovalComments] NVARCHAR(MAX) NULL,
    [ApprovedByUserID] UNIQUEIDENTIFIER NULL,
    [ApprovedAt] DATETIMEOFFSET NULL,
    [ApprovedFingerprint] NVARCHAR(100) NULL,
    CONSTRAINT [CK_UserView_ApprovalStatus] CHECK ([ApprovalStatus] IN (N'Pending', N'Approved', N'Rejected')),
    CONSTRAINT [FK_UserView_ApprovedByUserID] FOREIGN KEY ([ApprovedByUserID]) REFERENCES [${flyway:defaultSchema}].[User]([ID]);
GO

ALTER TABLE [${flyway:defaultSchema}].[Dashboard] ADD
    [ApprovalStatus] NVARCHAR(20) NOT NULL CONSTRAINT [DF_Dashboard_ApprovalStatus] DEFAULT N'Pending',
    [ApprovalComments] NVARCHAR(MAX) NULL,
    [ApprovedByUserID] UNIQUEIDENTIFIER NULL,
    [ApprovedAt] DATETIMEOFFSET NULL,
    [ApprovedFingerprint] NVARCHAR(100) NULL,
    CONSTRAINT [CK_Dashboard_ApprovalStatus] CHECK ([ApprovalStatus] IN (N'Pending', N'Approved', N'Rejected')),
    CONSTRAINT [FK_Dashboard_ApprovedByUserID] FOREIGN KEY ([ApprovedByUserID]) REFERENCES [${flyway:defaultSchema}].[User]([ID]);
GO

ALTER TABLE [${flyway:defaultSchema}].[Component] ADD
    [ApprovalStatus] NVARCHAR(20) NOT NULL CONSTRAINT [DF_Component_ApprovalStatus] DEFAULT N'Pending',
    [ApprovalComments] NVARCHAR(MAX) NULL,
    [ApprovedByUserID] UNIQUEIDENTIFIER NULL,
    [ApprovedAt] DATETIMEOFFSET NULL,
    [ApprovedFingerprint] NVARCHAR(100) NULL,
    CONSTRAINT [CK_Component_ApprovalStatus] CHECK ([ApprovalStatus] IN (N'Pending', N'Approved', N'Rejected')),
    CONSTRAINT [FK_Component_ApprovedByUserID] FOREIGN KEY ([ApprovedByUserID]) REFERENCES [${flyway:defaultSchema}].[User]([ID]);
GO

